using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using SuperDock;
class Check{[STAThread]static void Main(){var app=new App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var assembly=typeof(App).Assembly;var type=assembly.GetType("SuperDock.MessageGlass")!;foreach(var mode in new[]{"Light","Dark"}){assembly.GetType("SuperDock.Theme")!.GetMethod("Apply")!.Invoke(null,new object[]{mode});foreach(var opacity in new[]{.2,.65,1}){var brush=(LinearGradientBrush)type.GetMethod("PopupSurface")!.Invoke(null,new object[]{"微信",opacity})!;if(brush.GradientStops.Any(s=>Math.Abs(s.Color.A-opacity*255)>1))throw new Exception("Background alpha mismatch");}Console.WriteLine("PASS background transparency "+mode);}
var settings=new MainWindow.Settings{MessageReminderOpacity=.35,Entries=[],Groups=[],SmartLayering=false};var window=(MainWindow)Activator.CreateInstance(typeof(MainWindow),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{settings,false},null)!;window.Show();window.UpdateLayout();var reminders=assembly.GetType("SuperDock.MessageReminders")!;reminders.GetMethod("Display")!.Invoke(null,new object[]{window,"微信","透明度测试",IntPtr.Zero});var toast=(Window)reminders.GetField("toast",BindingFlags.NonPublic|BindingFlags.Static)!.GetValue(null)!;if(!toast.AllowsTransparency)throw new Exception("Window is not layered");reminders.GetMethod("UpdateOpacity")!.Invoke(null,new object[]{.2});var border=(Border)toast.Content;if(((LinearGradientBrush)border.Background).GradientStops[0].Color.A!=51||border.Child.Opacity!=1)throw new Exception("Live update or foreground opacity failed");Console.WriteLine("PASS transparent window, live background updates, foreground unchanged");toast.Close();window.Close();app.Shutdown();}}
